    const parts = message.split(/(@\S+\s)/g);

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      if (part.match(/^@\S+\s$/)) {
        // If we have accumulated text before this @mention, add it as a separate part
        if (currentPart) {
          messageParts.push(currentPart);
          currentPart = '';
        }
        // Add the @mention as its own part
