				field: "revoked",
				operator: "eq",
				value: null,
			},
		],
		update: {
			revoked: new Date(iat * 1000),
		},
	});
	if (!won) {
		await invalidateRefreshFamily(ctx, clientId, refreshToken.userId);
		throw new APIError("BAD_REQUEST", {
			error_description: "refresh token revoked",
			error: "invalid_request",
		});
